<script setup lang="ts">
import {watch} from 'vue';import BusinessCategorySelect from './BusinessCategorySelect.vue';
const systems=[{code:'GENERAL',name:'通用业务系统'},{code:'SPACE',name:'观测规划系统'},{code:'USER_CENTER',name:'用户中心'},{code:'user-mgmt',name:'业务用户管理系统'}];
const roleOptions=[{code:'ADMIN',name:'平台管理员'},{code:'EDITOR',name:'平台编辑者'},{code:'APPROVER',name:'平台审批者'},{code:'UM_OPERATOR',name:'业务操作员'},{code:'UM_APPROVER',name:'部门负责人'},{code:'UM_SECURITY',name:'安全复核员'},{code:'SPACE_OPERATOR',name:'观测操作员'},{code:'VIEWER',name:'只读人员'}];
const props=defineProps<{value:any}>();
watch(()=>props.value,v=>{v.bizCategories||=['GENERAL'];v.businessSystemCode||='GENERAL';v.accessPolicy||={visibility:'PUBLIC',viewRoles:[],configureRoles:[],invokeRoles:[]};},{immediate:true});
</script>
<template><el-form label-position="top"><el-form-item label="业务分类"><BusinessCategorySelect v-model="value.bizCategories" multiple /></el-form-item><el-form-item label="所属业务系统"><el-select v-model="value.businessSystemCode" filterable allow-create><el-option v-for="system in systems" :key="system.code" :value="system.code" :label="`${system.name}（${system.code}）`" /></el-select></el-form-item><el-form-item label="可见范围"><el-select v-model="value.accessPolicy.visibility"><el-option label="公开" value="PUBLIC" /><el-option label="角色可见" value="RESTRICTED" /><el-option label="业务系统" value="BUSINESS" /><el-option label="私有" value="PRIVATE" /></el-select></el-form-item><el-form-item v-for="field in [{key:'viewRoles',label:'可查看角色'},{key:'configureRoles',label:'可配置角色'},{key:'invokeRoles',label:'可调用角色'}]" :key="field.key" :label="field.label"><el-select v-model="value.accessPolicy[field.key]" multiple filterable allow-create placeholder="输入角色编码并回车"><el-option v-for="role in roleOptions" :key="role.code" :value="role.code" :label="`${role.name}（${role.code}）`" /></el-select></el-form-item></el-form></template>
